function y = single_expm1_func(x_in)

%   Copyright 2017 The MathWorks, Inc.

    x_in = single(x_in);
    y = coder.nullcopy(x_in);
    for ii=1:numel(x_in)
        y(ii) = single_expm1_scalar(x_in(ii));
    end
end

function y = single_expm1_scalar(x_in)
    [s, exp, mant] = sflt_extract(sflt(x_in));

    % for small values, y = x
    
    fm = fimath(hdlfimath, 'ProductMode', 'SpecifyPrecision', ...
                           'ProductWordLength', 48, ...
                           'ProductFractionLength', 46);
%     x_exp_s = fi(exp > 0, 0, 1, 0, hdlfimath);
    x_exp = fi(-exp, 0, 7, 0, hdlfimath);
    x1 = fi(mant, 1, 48, 46, fm); % Use only single precision of x
    exp_check = fi(x1.WordLength -24, 0, 5, 0);
    
    if x_exp < exp_check
%         if x_exp_s            % Since x_exp is always in {-127,...,-1,0}
            x1 = bitsra(x1, x_exp);
%         else
%             x1 = bitsll(x1, x_exp); % hdl_srl
%         end
        res = remez_expm1(x1,s);
        y = cast(res,'like',x_in);
    else
        x1 = x1; 
        y = x_in; % cast(0, 'like', x1);
    end

end



