             [  0.9864275821336717     0.44646011718304024     0.09231142020598782 ] % Domain = [-0.796875 -0.8125],  Max-error = 2.6329860514096026E-09
             [  0.9857482514540811     0.44478790097788234     0.09128234531453927 ] % Domain = [-0.8125 -0.828125],  Max-error = 2.6012219045412621E-09
             [  0.9850510521612634     0.44310408129368994     0.09026568128956569 ] % Domain = [-0.828125 -0.84375],  Max-error = 2.5698602135193482E-09
             [  0.9843360182913345     0.44140916857834256      0.0892612709540117 ] % Domain = [-0.84375 -0.859375],  Max-error = 2.5388956492733428E-09
             [  0.9836031910319996     0.43970366208041156     0.08826895918809896 ] % Domain = [-0.859375 -0.875],  Max-error = 2.50832299375503E-09
             [  0.9828526184528055      0.4379880500328248     0.08728859288748936 ] % Domain = [-0.875 -0.890625],  Max-error = 2.4781370289161941E-09
             [  0.9820843552752292     0.43626280990963195     0.08632002096601354 ] % Domain = [-0.890625 -0.90625],  Max-error = 2.4483328697755269E-09
             [  0.9812984626197621     0.43452840860944875     0.08536309431747213 ] % Domain = [-0.90625 -0.921875],  Max-error = 2.4189055203294174E-09
             [   0.980495007749751      0.4327853026170594     0.08441766576925147 ] % Domain = [-0.921875 -0.9375],  Max-error = 2.38984976252965E-09
             [  0.9796740638601222     0.43103393824689107     0.08348359008323314 ] % Domain = [-0.9375 -0.953125],  Max-error = 2.3611610444618236E-09
             [  0.9788357098384837      0.4292747518085882     0.08256072391577618 ] % Domain = [-0.953125 -0.96875],  Max-error = 2.3328343701223275E-09
             [  0.9779800300518898     0.42750816981218165      0.0816489258013462 ] % Domain = [-0.96875 -0.984375],  Max-error = 2.3048652986190632E-09
             [  0.9771071141172587      0.4257346091239498     0.08074805611249758 ] % Domain = [-0.984375 -1],  Max-error = 2.2772489449707223E-09
         ],nt,fm);

     
     %% Evaluatung Polynomial
     
    domain = fi((bitsliceget(x1, x1.FractionLength, x1.FractionLength-6+1)), 0, 7, 0); % first 6 fractional bits
    domain(:) = setfimath(domain, hdlfimath);
    domain(:) = domain + cast(1,'like',domain);      % MATLAB indexin
    cor = fi(x1 == 1,0,1,0);                         % Correction for boundary case {-1,+1}
    if cor
        domain(:) = cast(64,'like',domain);
    end
    if s ~= 0
        x = -x;
    end
        
    coeffs_positive = coeffs_pos_table(domain, :);
    coeffs_negative = coeffs_neg_table(domain, :);
    
    if s == 0
        coeffs = coeffs_positive;
    else
        coeffs = coeffs_negative;
    end
    
    res = fi(coeffs(end), nt, fm);
    for ii=numel(coeffs):-1:2
        res(:) = res*x + coeffs(ii-1);
    end
    
    res = fi(res, 1, x.WordLength, x.FractionLength, hdlfimath, fm);
%     res = fi(res, fm);
    x = fi(x, fm);
    y = res * cast(x, 'like', res);
end